func ControlCalcDiff(component float64, factor float64, wantDarker bool) float64 {
	if wantDarker {
		return component * -1 * factor
	} else {
		return (1 - component) * factor
	}
}

func ControlGetLighterOrDarkerColor(pixel []float64, factor float64, wantDarker bool) []float64 {
	var red float64 = pixel[0]
	var green float64 = pixel[1]
	var blue float64 = pixel[2]
	red += ControlCalcDiff(red, factor, wantDarker)
	green += ControlCalcDiff(green, factor, wantDarker)
	blue += ControlCalcDiff(blue, factor, wantDarker)
	return []float64{red, green, blue, pixel[3]}
}

func ControlLuma(rgbColor []float64) float64 {
	return 0.2126*rgbColor[0] + 0.7152*rgbColor[1] + 0.0722*rgbColor[2]
}

